def may_delete(role, actor_tenant, record_tenant):
    return role == "admin" or actor_tenant == record_tenant

def delete_record(records, index, role, actor_tenant):
    record = records[index]
    if not may_delete(role, actor_tenant, record["tenant"]):
        raise PermissionError("not permitted")
    return records.pop(index)

